using System.Windows;using System.Windows.Controls;using System.Windows.Threading;using System.Diagnostics;using Microsoft.Win32;using FacialPresets;
namespace FacialStudio;
public sealed class ClipPanel:StackPanel {
 FacialClip clip=new();readonly Action<Preset?> display;readonly Func<Preset> current;readonly ListBox keys=new(){Height=65};readonly Slider scrub=new(){Minimum=0,Maximum=2};readonly TextBox title=new(){Text=L.T("새 클립"),Width=110},duration=new(){Text="2",Width=50},time=new(){Text="0",Width=55};readonly ComboBox interpolation=new(){ItemsSource=new[]{"Linear","Hold"},SelectedIndex=0};readonly CheckBox enabled=new(){Content=L.T("클립 편집 모드")},loop=new(){Content=L.T("반복")};readonly DispatcherTimer timer=new(){Interval=TimeSpan.FromMilliseconds(33)};readonly Stopwatch clock=new();double anchor;bool updating,playing;public bool Dirty{get;private set;}public bool Playing=>playing;public bool Active=>enabled.IsChecked==true;FacialKey? selected;string? path,lastSignature;
 public ClipPanel(Action<Preset?> show,Func<Preset> get){display=show;current=get;var toolbar=new WrapPanel();Children.Add(toolbar);toolbar.Children.Add(enabled);void B(string label,Action action){var b=new Button{Content=label,Margin=new Thickness(2)};b.Click+=(_,_)=>{try{action();}catch(Exception e){MessageBox.Show(L.T(e.Message),L.T("표정 클립"));}finally{if(Window.GetWindow(this) is {} w)L.Apply(w);}};toolbar.Children.Add(b);}
  B(L.T("새 클립"),()=>{if(!Discard())return;Pause();clip=new(){Profile=current().Profile};path=null;Dirty=true;selected=null;Refresh();Activate();});B(L.T("클립 열기"),Open);B(L.T("클립 저장"),Save);toolbar.Children.Add(title);toolbar.Children.Add(duration);B(L.T("이름·길이 적용"),()=>{var old=(clip.Name,clip.Duration);try{clip.Name=title.Text;clip.Duration=Number(duration);FacialClipFile.Validate(clip);}catch{(clip.Name,clip.Duration)=old;throw;}Dirty=true;Refresh();});toolbar.Children.Add(time);toolbar.Children.Add(interpolation);
  B(L.T("현재 상태 추가"),()=>{var state=FacialTimeline.Copy(current());var target=time.Text;Activate();time.Text=target;AddState(state);});B(L.T("키 시간·보간 적용"),()=>{if(selected==null)return;var old=(selected.Time,selected.Interpolation);try{selected.Time=Number(time);selected.Interpolation=interpolation.SelectedItem as string??"Linear";FacialClipFile.Validate(clip);}catch{(selected.Time,selected.Interpolation)=old;throw;}Dirty=true;Refresh();keys.SelectedItem=selected;if(selected is {} key)SelectKey(key);});B(L.T("키 복제"),()=>{if(selected!=null)AddState(selected.State);});B(L.T("키 삭제"),()=>{if(selected==null)return;Pause();clip.Keys.Remove(selected);selected=null;Dirty=true;Refresh();ShowTime();});B(L.T("프리셋 가져오기"),Import);B(L.T("현재 상태를 프리셋 저장"),ExportPreset);B(L.T("재생 / 일시정지"),()=>{if(playing){Pause();ShowTime(true);return;}Activate();selected=null;anchor=scrub.Value>=clip.Duration?0:scrub.Value;clock.Restart();playing=true;ShowTime(true);timer.Start();});toolbar.Children.Add(loop);Children.Add(scrub);Children.Add(keys);
  scrub.ValueChanged+=(_,_)=>{if(updating)return;Pause();selected=null;ShowTime(true);};keys.SelectionChanged+=(_,_)=>{if(!updating&&keys.SelectedItem is FacialKey k)SelectKey(k);};
  enabled.Checked+=(_,_)=>ShowTime(true);enabled.Unchecked+=(_,_)=>{Pause();display(null);};timer.Tick+=(_,_)=>{double t=anchor+clock.Elapsed.TotalSeconds;if(t>=clip.Duration){if(loop.IsChecked==true)t%=clip.Duration;else{t=clip.Duration;Pause();}}updating=true;scrub.Value=t;updating=false;ShowTime();};Unloaded+=(_,_)=>Pause();Refresh();
 }
 void SelectKey(FacialKey k){Pause();selected=k;updating=true;scrub.Value=k.Time;time.Text=k.Time.ToString("R",System.Globalization.CultureInfo.InvariantCulture);interpolation.SelectedItem=k.Interpolation;updating=false;if(Active)display(k.State);}
 static double Number(TextBox b)=>double.Parse(b.Text,System.Globalization.CultureInfo.InvariantCulture);
 public void Pause(){playing=false;timer.Stop();clock.Stop();}
 bool Discard()=>!Dirty||MessageBox.Show(L.T("클립의 미저장 변경을 버릴까요?"),L.T("클립"),MessageBoxButton.YesNo)==MessageBoxResult.Yes;
 void Activate(){enabled.IsChecked=true;ShowTime(true);}
 void Refresh(){updating=true;title.Text=clip.Name;duration.Text=clip.Duration.ToString("R",System.Globalization.CultureInfo.InvariantCulture);scrub.Maximum=clip.Duration;scrub.TickPlacement=System.Windows.Controls.Primitives.TickPlacement.BottomRight;scrub.Ticks=new System.Windows.Media.DoubleCollection(clip.Keys.Select(k=>k.Time));keys.ItemsSource=clip.Keys.OrderBy(k=>k.Time).ToList();keys.DisplayMemberPath="Time";updating=false;lastSignature=null;}
 void ShowTime(bool force=false){time.Text=scrub.Value.ToString("0.###",System.Globalization.CultureInfo.InvariantCulture);if(!Active)return;var state=clip.Evaluate(scrub.Value);string signature=System.Text.Json.JsonSerializer.Serialize(state.Channels);if(!force&&signature==lastSignature)return;lastSignature=signature;display(state);}
 void AddState(Preset state){Pause();double t=Number(time);var copy=FacialTimeline.Copy(state);if(clip.Keys.Count==0)clip.Profile=copy.Profile;else if(copy.Profile!=clip.Profile)throw new InvalidOperationException(L.T("프리셋과 클립의 종족 프로필이 다릅니다."));var k=new FacialKey{Time=t,State=copy,Interpolation=interpolation.SelectedItem as string??"Linear"};clip.Keys.Add(k);try{FacialClipFile.Validate(clip);}catch{clip.Keys.Remove(k);throw;}clip.RequiredResources=clip.RequiredResources.Concat(clip.Keys.SelectMany(k=>k.State.RequiredResources)).Distinct().ToList();selected=k;Dirty=true;Refresh();keys.SelectedItem=k;SelectKey(k);}
 public void Edited(Preset state){if(!Active)return;Pause();selected??=clip.Keys.FirstOrDefault(k=>Math.Abs(k.Time-scrub.Value)<1e-9);if(selected!=null){selected.State=state;Dirty=true;}else{AddState(state);}lastSignature=null;}
 void Open(){var d=new OpenFileDialog{Filter=L.T("표정 클립|*.facialclip.json;*.json")};if(d.ShowDialog()!=true)return;var loaded=FacialClipFile.Load(d.FileName);if(!Discard())return;Pause();clip=loaded;path=d.FileName;selected=null;Dirty=false;Refresh();Activate();ShowTime();}
 void Save(){var d=new SaveFileDialog{Filter=L.T("표정 클립|*.facialclip.json"),FileName=path??"clip.facialclip.json"};if(d.ShowDialog()!=true)return;clip.RequiredResources=clip.RequiredResources.Concat(clip.Keys.SelectMany(k=>k.State.RequiredResources)).Distinct().ToList();FacialClipFile.Save(d.FileName,clip);path=d.FileName;Dirty=false;}
 void Import(){var d=new OpenFileDialog{Filter=L.T("표정 프리셋|*.facialpreset.json;*.json")};if(d.ShowDialog()!=true)return;var p=PresetFile.Load(d.FileName);var target=time.Text;Activate();time.Text=target;AddState(p);}
 void ExportPreset(){var d=new SaveFileDialog{Filter=L.T("표정 프리셋|*.facialpreset.json"),FileName="frame.facialpreset.json"};if(d.ShowDialog()==true)PresetFile.Save(d.FileName,current());}
}
